local ApothecaryMortarMaker = {}
local PRODUCTS = {
    simple_stone_mortar = { name = "Preprost kamnit možnar", stoneCost = 2, woodCost = 1, time = 3, cost = 40, science = 18, healing = 5, happiness = 1, description = "Preprost kamnit možnar za zdravilstvo." },
    bronze_pestle_mortar = { name = "Bronastozgiban možnar", stoneCost = 1, bronzeCost = 2, woodCost = 1, time = 6, cost = 130, science = 32, healing = 12, happiness = 2, prestige = 2, description = "Bronastozgiban možnar za trgovce." },
    marble_apothecary_mortar = { name = "Marmornat aptekarski možnar", marbleCost = 2, bronzeCost = 1, woodCost = 1, time = 9, cost = 320, science = 48, healing = 22, happiness = 2, prestige = 6, description = "Marmornat aptekarski možnar za plemiče." },
    silver_rim_mortar = { name = "Srebrnookrasni možnar", marbleCost = 2, silverCost = 2, bronzeCost = 1, woodCost = 1, time = 13, cost = 760, science = 62, healing = 35, happiness = 3, prestige = 14, description = "Srebrnookrasni možnar za visoke plemiče." },
    gold_inlaid_mortar = { name = "Zlatovloženi možnar", marbleCost = 2, goldCost = 2, silverCost = 1, bronzeCost = 1, woodCost = 1, jewelCost = 1, time = 17, cost = 1700, science = 78, healing = 50, happiness = 5, prestige = 27, description = "Zlatovloženi možnar z draguljem za visoko plemstvo." },
    royal_grand_mortar = { name = "Kraljevski veliki možnar", marbleCost = 3, goldCost = 3, silverCost = 2, bronzeCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, science = 92, healing = 75, happiness = 12, prestige = 58, description = "Veliki kraljevski možnar z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mortar_workshop = { name = "Možnarska delavnica", cost = { gold = 220, wood = 100, stone = 120, marble = 4 }, upkeep = 5, qualityBonus = 5 },
    apothecary_loft = { name = "Aptekarska podstrešje", cost = { gold = 820, wood = 240, stone = 240, bronze = 6, silver = 6 }, upkeep = 19, qualityBonus = 18 },
    master_apothecary_atelier = { name = "Mojstrski aptekarski atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_mortar_palace = { name = "Kraljevska možnarska palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
ApothecaryMortarMaker.stoneStock = 14; ApothecaryMortarMaker.marbleStock = 12; ApothecaryMortarMaker.woodStock = 10; ApothecaryMortarMaker.bronzeStock = 10; ApothecaryMortarMaker.silverStock = 6; ApothecaryMortarMaker.goldStock = 6; ApothecaryMortarMaker.jewelStock = 4; ApothecaryMortarMaker.pearlStock = 4
ApothecaryMortarMaker.productStock = {}; ApothecaryMortarMaker.buildings = {}; ApothecaryMortarMaker.maker = nil; ApothecaryMortarMaker.activeMaking = {}; ApothecaryMortarMaker.totalProducts = 0; ApothecaryMortarMaker.dayTimer = 0
function ApothecaryMortarMaker.init() ApothecaryMortarMaker.stoneStock=14; ApothecaryMortarMaker.marbleStock=12; ApothecaryMortarMaker.woodStock=10; ApothecaryMortarMaker.bronzeStock=10; ApothecaryMortarMaker.silverStock=6; ApothecaryMortarMaker.goldStock=6; ApothecaryMortarMaker.jewelStock=4; ApothecaryMortarMaker.pearlStock=4; ApothecaryMortarMaker.productStock={}; ApothecaryMortarMaker.buildings={}; ApothecaryMortarMaker.maker=nil; ApothecaryMortarMaker.activeMaking={}; ApothecaryMortarMaker.totalProducts=0; ApothecaryMortarMaker.dayTimer=0; print("[ApothecaryMortarMaker] Royal Apothecary Mortar Maker System initialized (6 products, 4 buildings)") end
function ApothecaryMortarMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ApothecaryMortarMaker.maker={name=n or ("Možnarjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnarjar najet: %s (spretnost: %d)",ApothecaryMortarMaker.maker.name,s),"success") end; return true end
function ApothecaryMortarMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ApothecaryMortarMaker.build(id) local ok,e=ApothecaryMortarMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ApothecaryMortarMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ApothecaryMortarMaker.getQualityBonus() local b=0; for _,bd in ipairs(ApothecaryMortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ApothecaryMortarMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and ApothecaryMortarMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and ApothecaryMortarMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.woodCost and ApothecaryMortarMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.bronzeCost and ApothecaryMortarMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and ApothecaryMortarMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ApothecaryMortarMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ApothecaryMortarMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ApothecaryMortarMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ApothecaryMortarMaker.buildings==0 then return false,"Potrebna možnarska delavnica" end; if not ApothecaryMortarMaker.maker then return false,"Potreben možnarjar" end; return true end
function ApothecaryMortarMaker.make(pt,qty) qty=qty or 1; local ok,e=ApothecaryMortarMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then ApothecaryMortarMaker.stoneStock=ApothecaryMortarMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then ApothecaryMortarMaker.marbleStock=ApothecaryMortarMaker.marbleStock-d.marbleCost*qty end; if d.woodCost then ApothecaryMortarMaker.woodStock=ApothecaryMortarMaker.woodStock-d.woodCost*qty end; if d.bronzeCost then ApothecaryMortarMaker.bronzeStock=ApothecaryMortarMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then ApothecaryMortarMaker.silverStock=ApothecaryMortarMaker.silverStock-d.silverCost*qty end; if d.goldCost then ApothecaryMortarMaker.goldStock=ApothecaryMortarMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ApothecaryMortarMaker.jewelStock=ApothecaryMortarMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ApothecaryMortarMaker.pearlStock=ApothecaryMortarMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ApothecaryMortarMaker.maker then t=math.max(1,t-math.floor(ApothecaryMortarMaker.maker.skill/13)) end; table.insert(ApothecaryMortarMaker.activeMaking,{id="mortar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,healing=d.healing or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ApothecaryMortarMaker.completeMaking(m) local q=1.0+(ApothecaryMortarMaker.getQualityBonus()/100); if ApothecaryMortarMaker.maker then q=q+(ApothecaryMortarMaker.maker.skill/150) end; q=math.min(2.4,q); ApothecaryMortarMaker.productStock[m.productType]=(ApothecaryMortarMaker.productStock[m.productType] or 0)+m.quantity; ApothecaryMortarMaker.totalProducts=ApothecaryMortarMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.healing>0 and _G.state then _G.state.medicine=(_G.state.medicine or 0)+m.healing end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ApothecaryMortarMaker.maker then ApothecaryMortarMaker.maker.itemsMade=ApothecaryMortarMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ApothecaryMortarMaker.maker.skill=math.min(100,ApothecaryMortarMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mortar.completed",{productName=m.productName,science=m.science,healing=m.healing,prestige=m.prestige,happiness=m.happiness}) end end
function ApothecaryMortarMaker.update(dt) if not _G.state then return end; ApothecaryMortarMaker.dayTimer=ApothecaryMortarMaker.dayTimer+dt; if ApothecaryMortarMaker.dayTimer>=30 then ApothecaryMortarMaker.dayTimer=0; for i=#ApothecaryMortarMaker.activeMaking,1,-1 do local m=ApothecaryMortarMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ApothecaryMortarMaker.completeMaking(m); table.remove(ApothecaryMortarMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ApothecaryMortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ApothecaryMortarMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ApothecaryMortarMaker.getStats() return {stoneStock=ApothecaryMortarMaker.stoneStock,marbleStock=ApothecaryMortarMaker.marbleStock,woodStock=ApothecaryMortarMaker.woodStock,bronzeStock=ApothecaryMortarMaker.bronzeStock,silverStock=ApothecaryMortarMaker.silverStock,goldStock=ApothecaryMortarMaker.goldStock,jewelStock=ApothecaryMortarMaker.jewelStock,pearlStock=ApothecaryMortarMaker.pearlStock,productStock=ApothecaryMortarMaker.productStock,numBuildings=#ApothecaryMortarMaker.buildings,hasMaker=ApothecaryMortarMaker.maker~=nil,makerName=ApothecaryMortarMaker.maker and ApothecaryMortarMaker.maker.name or "—",makerSkill=ApothecaryMortarMaker.maker and ApothecaryMortarMaker.maker.skill or 0,activeMaking=#ApothecaryMortarMaker.activeMaking,totalProducts=ApothecaryMortarMaker.totalProducts} end
return ApothecaryMortarMaker
